import sys
from collections import defaultdict

def find_largest_x_and_permutation(n, s):
    def dfs(node, visited, path, x):
        if node in visited:
            return False
        visited[node] = True
        path.append(node)
        for neighbor in graph[node]:
            if not visited[neighbor]:
                if dfs(neighbor, visited, path, x):
                    return True
        return len(path) == (1 << x)

    max_x = 0
    best_permutation = [0]
    for x in range(1, 20):  # 2^20 > 2 * 10^5
        limit = 1 << x
        if limit > max(s):
            break
        graph = defaultdict(list)
        for i in range(limit):
            for j in range(limit):
                if i ^ j in s:
                    graph[i].append(j)
                    graph[j].append(i)

        visited = [False] * limit
        path = []
        if dfs(0, visited, path, x):
            max_x = x
            best_permutation = path

    return max_x, best_permutation

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    s = list(map(int, input[1:n+1]))
    x, permutation = find_largest_x_and_permutation(n, s)
    print(x)
    print(" ".join(map(str, permutation)))

if __name__ == "__main__":
    main()
